std::vector<double> k1 = f(x, t);
std::vector<double> k2 = f(std::vector<double>(x.begin(), x.end() + std::transform(x.begin(), x.end(), k1.begin(), x.begin(),
    [h](double xi, double k1i) { return xi + h * k1i / 2.0; })), t + h / 2.0);
std::vector<double> k3 = f(std::vector<double>(x.begin(), x.end() + std::transform(x.begin(), x.end(), k2.begin(), x.begin(),
    [h](double xi, double k2i) { return xi + h * k2i / 2.0; })), t + h / 2.0);
std::vector<double> k4 = f(std::vector<double>(x.begin(), x.end() + std::transform(x.begin(), x.end(), k3.begin(), x.begin(),
    [h](double xi, double k3i) { return xi + h * k3i; })), t + h);

std::vector<double> next_state(x.size());
for (std::size_t i = 0; i < x.size(); ++i) {
    next_state[i] = x[i] + h / 6.0 * (k1[i] + 2.0 * k2[i] + 2.0 * k3[i] + k4[i]);
}
return next_state;

